export const algorithmId = (number: StoryLessonNumber) => `conversational-skills-L7-C2-${number}-${algorithmEpisodes[number].skill}-en-v1`;

export function buildAlgorithmLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, algorithmEpisodes[number], previous, reference, {
    id: algorithmId(number), chapterName: 'The Algorithm Never Sleeps', pronunciation: algorithmPronunciation[number],
    setting: 'Spotlight Works, a fictional entertainment agency in Shibuya, Tokyo. The team works with performance footage, an independent journalist, a recording studio and a Tokyo music showcase.',
    previousSummary: index === 0 ? spotlightEpisodes[9].closing : algorithmEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(7)}\nReference: Beyond the Spotlight, Chapter 2: The Algorithm Never Sleeps. Owner target is TOEIC 550-780, overriding the supplied C1-C2 subtitle. Map eight source episodes to slots 1-4 and 6-9; leave 5/10 as dynamic checkpoints. English only; four Step A expressions; only Step B pronunciation with bold stress; no Part III or extra pronunciation commentary. Tutor-first short dialogue, private listening, fresh reading missions, fixed English feedback. No new artwork or romance. Continue Maya, Natsumi, Jisoo, Luis and Kai. Tuesday: decide to release original footage with brief explanation. Following afternoon: venue permission precedes publication; thousands watch, some apologise and others disagree. Fan support is unsolicited and individual; no attacks on critics. Friday: preliminary call with independent journalist Rika Morimoto clarifies music, controversy and public expectations, not editorial control or an already completed interview. Do not connect Rika to Chapter 1’s two publication enquiries without evidence. Similar captions and close timestamps suggest a pattern, not proof of coordination or an identified culprit. Copying and automated reposting remain possible explanations. Team documents and reports through available channels; no platform verdict or removed accounts. Monday interview is completed before later publication; Kai corrects the context while recognising communication responsibility. Later organisers review full footage and team response and reinstate invitation for next month. Published interview is encouraging, not unanimous approval or sole proven cause of reinstatement. Kai confirms readiness to team; rehearsal filming remains a suggestion. One month later: successful Tokyo showcase, Paper Skyline officially released earlier that week, warm audience response. Mr. Shibata of major company Apex Entertainment wants to discuss a possible recording agreement. No signed deal, formal terms, money, rights or creative restrictions are supplied. Interest and discussion are not acceptance. End with terms and expectations to examine, not a resolved agreement.`,
  });
  lesson.storyData.storyTitle = 'Beyond the Spotlight';
  lesson.storyData.characters = [
    { id: 'maya', name: 'Maya Kurose', role: 'main', description: 'Creative producer at Spotlight Works. She balances clear evidence, careful responses and the artist’s interests.' },
    { id: 'natsumi', name: 'Natsumi Ito', role: 'supporting', description: 'Talent manager who coordinates the interview and showcase, and wants to review proposed business terms.' },
    { id: 'jisoo', name: 'Jisoo', role: 'supporting', description: 'Digital marketing strategist. She follows reactions, considers alternate explanations for repeated posts and prepares promotion.' },
    { id: 'luis', name: 'Luis', role: 'supporting', description: 'Videographer who prepares the full recording, notices repeated posts and proposes rehearsal footage.' },
    { id: 'kai', name: 'Kai Nakamura', role: 'supporting', description: 'Singer-songwriter behind Paper Skyline. He explains the lyric mistake, performs at the showcase and considers a possible recording opportunity.' },
    { id: 'rika', name: 'Rika Morimoto', role: 'supporting', description: 'Independent entertainment journalist who interviews Kai about music, the controversy and public expectations.' },
    { id: 'shibata', name: 'Mr. Shibata', role: 'supporting', description: 'Representative of Apex Entertainment. After the showcase, he invites a discussion about a possible recording agreement.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 7, chapter: 2, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 2: The Algorithm Never Sleeps', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildAlgorithmChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildAlgorithmLesson(number, {}, reference));
}
